import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
var archive = Path.of("G:/JiBuildCache/ji-host-0.1.0-linux-x64-java21.tar.gz");
var dir = Path.of("G:/JiBuildCache/stage4-signing-001");
var hash = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(archive)));
var pair = KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
var payload = String.join("\n", "ji-host-bundle-v1", "0.1.0", "linux", "x64", hash, "Ed25519").getBytes(StandardCharsets.UTF_8);
var signer = Signature.getInstance("Ed25519");
signer.initSign(pair.getPrivate());
signer.update(payload);
var signature = Base64.getEncoder().encodeToString(signer.sign());
Files.writeString(dir.resolve("private.pk8"), Base64.getEncoder().encodeToString(pair.getPrivate().getEncoded()), StandardCharsets.US_ASCII);
Files.writeString(dir.resolve("public.key"), Base64.getEncoder().encodeToString(pair.getPublic().getEncoded()), StandardCharsets.US_ASCII);
var json = "{\"version\":\"0.1.0\",\"os\":\"linux\",\"architecture\":\"x64\",\"archiveSha256\":\"" + hash + "\",\"signatureAlgorithm\":\"Ed25519\",\"signature\":\"" + signature + "\"}";
Files.writeString(dir.resolve("manifest.json"), json, StandardCharsets.UTF_8);
System.out.println(hash);
